  "until" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "agreement") REFERENCES agreement ("tenant", "id"),
  FOREIGN KEY ("tenant", "terms") REFERENCES specification_pin ("tenant", "id")
