CREATE TABLE billing_charge (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "period" TEXT COLLATE "C" NOT NULL,
  "source_key" TEXT COLLATE "C" NOT NULL,
  "kind" TEXT COLLATE "C" NOT NULL,
  "rate" TEXT COLLATE "C",
  "meter" TEXT COLLATE "C",
  "usage_event" TEXT COLLATE "C",
  "adjustment" TEXT COLLATE "C",
  "adjustment_for" TEXT COLLATE "C",
  "definition" TEXT COLLATE "C" NOT NULL,
  "account" TEXT COLLATE "C" NOT NULL,
  "quantity" BIGINT NOT NULL,
  "amount" BIGINT NOT NULL,
