  "source" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "period") REFERENCES billing_period ("tenant", "id"),
  FOREIGN KEY ("tenant", "rate") REFERENCES pricing_rate ("tenant", "id"),
  FOREIGN KEY ("tenant", "meter") REFERENCES billing_meter_rate ("tenant", "id"),
  FOREIGN KEY ("tenant", "usage_event") REFERENCES usage_event ("tenant", "id"),
  FOREIGN KEY ("tenant", "adjustment") REFERENCES price_adjustment ("tenant", "id"),
  FOREIGN KEY ("tenant", "adjustment_for") REFERENCES billing_charge ("tenant", "id"),
  FOREIGN KEY ("tenant", "definition") REFERENCES specification_pin ("tenant", "id"),
  FOREIGN KEY ("tenant", "account") REFERENCES account ("tenant", "id")
